// Kotlin's prefetch: overlap work, and keep the data in a primitive layout.
import kotlinx.coroutines.*

suspend fun processAll(pages: List<Page>): List<Result> = coroutineScope {
    pages.mapIndexed { i, page ->
        async {
            val next = pages.getOrNull(i + 1)      // prefetch/warm the NEXT page
            next?.warm()                            // (a suspend call: overlaps I/O with compute)
            process(page)                           // I/O of page i overlaps fetch of page i+1
        }
    }.awaitAll()
}

